// Convierte el payload de Soro (u otra IA) en los datos de un artículo del blog.
// Tolerante: busca los campos habituales en varios nombres y niveles.
const TOKEN = 'CAMBIA-ESTE-TOKEN'; // el mismo que pongas en Soro como cabecera x-webhook-token o ?token=

const $in = $input.first().json;
const headers = $in.headers || {}; const query = $in.query || {};
if (TOKEN && (headers['x-webhook-token'] || query.token) !== TOKEN) {
  return [{ json: { valid: false, error: 'unauthorized' } }];
}
let raw = $in.body ?? $in;
for (const k of ['article', 'post', 'data', 'payload']) if (raw && typeof raw[k] === 'object' && raw[k]) raw = raw[k];

const pick = (...keys) => { for (const k of keys) { const v = k.split('.').reduce((o, p) => (o == null ? o : o[p]), raw); if (v !== undefined && v !== null && v !== '') return v; } return null; };
const strip = (h) => String(h || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
const slugify = (s) => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 80).replace(/-[^-]*$/, (m, o, str) => (str.length < 80 ? m : ''));
const cut = (s, n) => { s = String(s || '').trim(); if (s.length <= n) return s; const c = s.slice(0, n - 1); return c.slice(0, Math.max(20, c.lastIndexOf(' '))) + '…'; };

const title = pick('title', 'headline', 'seo_title', 'meta_title');
const html = pick('content_html', 'html', 'body_html', 'content', 'body');
const markdown = pick('content_markdown', 'markdown', 'body_markdown');
if (!title || (!html && !markdown)) return [{ json: { valid: false, error: 'missing title/content', raw } }];

const looksHtml = /<\/?[a-z][\s\S]*>/i.test(String(html || ''));
const slug = slugify(pick('slug', 'handle', 'url_slug') || title);
const description = cut(pick('meta_description', 'metaDescription', 'description', 'excerpt', 'summary', 'seo_description') || strip(html || markdown), 160);
const tagsRaw = pick('tags', 'keywords', 'categories') || [];
const tags = (Array.isArray(tagsRaw) ? tagsRaw : String(tagsRaw).split(',')).map((t) => (typeof t === 'object' ? (t.name || t.title || '') : String(t)).trim()).filter(Boolean).slice(0, 8);
const category = pick('category', 'category.name', 'primary_category') || tags[0] || 'Marketing digital';
const cover = pick('featured_image', 'featured_image_url', 'cover_image', 'cover', 'image', 'image_url', 'thumbnail', 'featuredImage.url', 'image.url');
const coverAlt = pick('featured_image_alt', 'image_alt', 'cover_alt', 'featuredImage.alt') || title;
const pubRaw = pick('published_at', 'publishedAt', 'date', 'created_at', 'pubDate');
const pubDate = (pubRaw && !isNaN(Date.parse(pubRaw)) ? new Date(pubRaw) : new Date()).toISOString().slice(0, 10);
const lang = String(pick('language', 'lang', 'locale') || 'es').toLowerCase().startsWith('en') ? 'en' : 'es';

return [{ json: {
  valid: true,
  slug, title: cut(title, 70), description, category: String(category), tags, pubDate, lang,
  cover: cover && /^https:\/\//.test(String(cover)) ? String(cover) : null, coverAlt: String(coverAlt).slice(0, 160),
  html: looksHtml ? String(html) : '',
  markdownReady: looksHtml ? '' : String(markdown || html || ''),
  status: pick('status', 'state') || 'published',
  raw,
}}];

// Une frontmatter + contenido Markdown → archivo .md para src/content/blog/
const d = $('Normalizar artículo').first().json;
const md = (d.markdownReady || $json.markdown || '').trim();
const q = (s) => JSON.stringify(String(s ?? ''));
const fm = [
  '---',
  `title: ${q(d.title)}`,
  `description: ${q(d.description)}`,
  `pubDate: ${d.pubDate}`,
  `lang: ${d.lang}`,
  `category: ${q(d.category)}`,
  `tags: ${JSON.stringify(d.tags)}`,
  d.cover ? `cover: ${q(d.cover)}` : null,
  d.cover ? `coverAlt: ${q(d.coverAlt)}` : null,
  'aiAssisted: true',
  'featured: false',
  'source: "soro"',
  `draft: ${d.status && !/publish|live|public/i.test(String(d.status)) ? 'true' : 'false'}`,
  '---',
].filter(Boolean).join('\n');
const path = `src/content/blog/${d.slug}.md`;
return [{ json: { path, slug: d.slug, title: d.title, content: fm + '\n\n' + md + '\n', message: `content(blog): ${d.title} [soro]` } }];
